#ifdef __cplusplus
#include <string>
#include <string.h>
#include <stdio.h>
#include <math.h>
#endif

#define VECI(n,i,x) for(int i=0;i<n;i++) {x;}
#define VEC(n,x) VECI(n,i,x)
#define VEC4(x) VEC(4,x)
#define VEC3(x) VEC(3,x)
#define VEC2(x) VEC(2,x)

#define N_RES 16
#define N_RES_F float(N_RES)

#ifdef __cplusplus

float iResolution[2]={1,75};

#define vec2 float *
#define vec3 float *
#define vec4 float *
#define Vec2(v) float v[2]
#define Vec3(v) float v[3]
#define Vec4(v) float v[4]
#define Vec2i(x,y)     {x,y}
#define Vec3i(x,y,z)   {x,y,z}
#define Vec4i(x,y,z,w) {x,y,z,w}
#define S_yz(v) &(v)[0]
#define S_xy(v) &(v)[1]
#define inout
#define in
#define out
#else
#define Vec2(v) vec2 v
#define Vec3(v) vec3 v
#define Vec4(v) vec4 v
#define Vec2i(x,y)     vec2(x,y)
#define Vec3i(x,y,z)   vec3(x,y,z)
#define Vec4i(x,y,z,w) vec4(x,y,z,w)
#define S_yz(v) (v).xy
#define S_xy(v) (v).yz
#endif

#ifdef __cplusplus
// not available in c++
float step(float a, float x) { return x>a?1.:0.; }
float mix(float a, float b, float f) { return a*(1.-f)+b*f; }
float fract(float f) { return f-floor(f); }
float clamp(float x, float min, float max) { return (x<min)?min:((x>max)?max:x); }
float smoothstep(float x1, float x2, float x) { float d = clamp((x-x1)/(x2-x1),0.,1.); return d*d*(3.-d-d); }
#endif

// those cannot be different depending on arg type in c++ (bc just float *)
float dot3(vec3 a, vec3 b) { return a[0]*b[0] + a[1]*b[1] + a[2]*b[2]; }
float length3(vec3 a) { return sqrt(dot3(a,a)); }
void  normalize3(inout vec3 a) { float l=length3(a); VEC3(a[i]/=l); }
void  ROT2(inout vec2 a, float ang) { Vec2(b); float s=sin(ang),c=cos(ang); VEC2(b[i]=a[i]); a[0]=b[0]*c+b[1]*s; a[1]=-b[0]*s+b[1]*c; }

float noise(int idx) { return fract(sin(float(idx)*121.1443+.25)*1341.); } // guess there's better noises than this one ;-)

void noiselin(vec2 uv_, inout vec4 c)
{
    Vec2(uv); VEC2(uv[i]=uv_[i]*N_RES_F);
    int x=int(floor(uv[0])); int y=int(floor(uv[1]));
    VEC4(c[i]=0.);
    for(int j=0; j<4; j++) {
        float fx=fract(uv[0]); if((j&1)==0) fx=1.-fx;
        float fy=fract(uv[1]); if((j/2)==0) fy=1.-fy;
        fx=smoothstep(0.,1.,fx);
        fy=smoothstep(0.,1.,fy);
        int idx=(((x+(j&1))&(N_RES-1))+((y+(j/2))&(N_RES-1))*N_RES)*4;
        VEC4(c[i]+=fx*fy*noise(idx+i));
    }
}

void noiselin3(vec3 uv3_, inout vec4 c)
{
    Vec3(uv3); VEC3(uv3[i]=uv3_[i]);
    Vec4(c1); Vec4(c2); float fr=fract(uv3[2]*N_RES_F), fl=floor(uv3[2]*N_RES_F);
    uv3[0]+=11./N_RES_F*fl; uv3[1]+=17./N_RES_F*fl; noiselin(S_xy(uv3),c1);
    uv3[0]+=11./N_RES_F;    uv3[1]+=17./N_RES_F;    noiselin(S_xy(uv3),c2);
    fr=smoothstep(0.,1.,fr);
    VEC4(c[i]=c1[i]*(1.-fr)+c2[i]*fr);
}

float dist(vec3 p)
{
    Vec3(p2); VEC3(p2[i]=p[i]);
    p2[2]-=(.6*sin(p[0])+.6*sin(p[1]));
    for( float sc=3.,cnt=1.; sc>.03; sc*=.6,cnt++ ) {
        Vec4(r2); Vec3(uv3);
        VEC3(uv3[i]=mix(p2[i],p[i],.25)/N_RES_F/sc); ROT2(S_xy(uv3),cnt); ROT2(S_yz(uv3),cnt);
        noiselin3(uv3,r2);
        VEC3(p2[i]+=(r2[i]-.5)*sc*.8);
        if (abs(p2[2])>sc) break;
    }
    return p2[2];
}

void getGrad(vec3 p, float eps, inout vec3 g)
{ Vec3(p1); Vec3(p2); VECI( 3, j, VEC3(p1[i]=p[i]); VEC3(p2[i]=p[i]); p1[j]+=eps*.5; p2[j]-=eps*.5; g[j]=(dist(p1)-dist(p2))/eps ); }

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    #ifndef __cplusplus
    fragCoord.x=fragCoord.x*.5+iMouse.x*10.+iTime*200.,fragCoord.y;
    #endif
    float H=iResolution[1], x=fragCoord[0], y=fragCoord[1];
    Vec3(pos)=Vec3i(0,+x*.003f,2.2);
    Vec3(pos0); VEC3(pos0[i]=pos[i]);
    float ph=x/H*2.*.2;
    float th=((y/H)-.5)*.27-.4*.27;
    Vec3(dir)=Vec3i(cos(ph)*cos(th),sin(ph)*cos(th),sin(th));
    for(int i=0;i<280;i++)
    {
        float d=dist(pos);
        VEC3(pos[i]=pos[i]+dir[i]*d*.35);
        if(d<.01) break;
        if(d>15.) break;
    }
    Vec3(light)=Vec3i(1,1,1);                  normalize3(light);
    Vec3(n)=Vec3i(0,0,0);  getGrad(pos,.02,n); normalize3(n);
    Vec3(col)=Vec3i(.0,.0,.0);
    float diff=clamp((dot3(n,light)),0.,1.);
    float br=1.;
    br+=-.2+pos[2]*.25;
    Vec3(ns)=Vec3i(1,-1,1);
    VEC3(col[i]=br*(.6+.6*n[(i+0)%3]*ns[i]));
    VEC3(pos0[i]-=pos[i]);
    float fog=exp(-length3(pos0)/47.);
    VEC3(col[i]=mix(col[i],.0,1.-fog));
    if(dist(pos)>1.) VEC3(col[i]=.0);
    float ao=1.;
    ao=0.; int anum=9; for(int j=0;j<anum;j++) { 
        Vec3(p2); Vec3(p3);
        float offLen=2.*exp2(-5.*float(j)/float(anum-1));
        VEC3(p2[i]=noise(i+j*3+2)-.5);
        VEC3(p3[i]=pos[i]-p2[i]*offLen); 
        VEC3(if(dot3(p2,n)<0.) p2[i]-=2.*dot3(p2,n)*n[i]);
        VEC3(p2[i]=pos[i]+p2[i]*offLen;); 
        ao+=step(0.,dist(p2)); 
        ao+=step(0.,dist(p3)); 
    } ao/=float(anum)*2.;
    VEC3(fragColor[i]=col[i]*ao*sqrt(ao)*1.5);
    fragColor[3]=1.;
}

#ifdef __cplusplus
const char *BR=" .,:;*iIUAB";
int   bitinvN(int x, int num) { int r=0,m=1<<(num-1); for(;m>0;x>>=1,m>>=1) r|=m*(x&1); return r; }
float bitinv_pat(int x, int y) { return float((15*bitinvN(y,8)+73*bitinvN(x,8))%255)/float(254); }
int br2c(float br) { int l=strlen(BR); return BR[(int)clamp(br*(float(l)-.01),0,l-1)]; }
int br2c_ht(float br,int x, int y) { int l=strlen(BR); br*=float(l)-.01; int bi=int(br); float bfr=br-bi; return BR[(int)clamp(bi+(bitinv_pat(x,y)+bfr>1.?1:0),0,l-1)]; }
const char * ansicol(float * c) {
#define CCMP(c,r,g,b) (int(c[0]+.5)==r && int(c[1]+.5)==g && int(c[2]+.5)==b)
//if( CCMP(c,0,0,0) ) return "\033[90;40m"; // black
    if( CCMP(c,0,0,0) ) return "\033[90m"; // black
    if( CCMP(c,0,0,0) ) return "\033[90m"; // black
    if( CCMP(c,1,0,0) ) return "\033[91m"; // red
    if( CCMP(c,0,1,0) ) return "\033[92m"; // green
    if( CCMP(c,0,0,1) ) return "\033[94m"; // blue
    if( CCMP(c,0,1,1) ) return "\033[96m"; // cyan
    if( CCMP(c,1,1,0) ) return "\033[93m"; // yellow
    if( CCMP(c,1,0,1) ) return "\033[95m"; // magenta
    if( CCMP(c,1,1,1) ) return "\033[97m"; // white
    return "";
}

const char * ansicolHT(float * c, int x, int y) {
    float c2[3]; VEC3(c2[i]=c[i]);
    c2[0]+=-.3+.6*bitinv_pat(x+11,y+3);
    c2[1]+=-.3+.6*bitinv_pat(x+3,y+7);
    c2[2]+=-.3+.6*bitinv_pat(x+7,y+11);
    return ansicol(c2);
}

float compmax3(vec3 c) { float cmax=c[0]; VEC3(if(c[i]>cmax)cmax=c[i]); return cmax; }
float compmin3(vec3 c) { float cmin=c[0]; VEC3(if(c[i]<cmin)cmin=c[i]); return cmin; }

int main(int argc, char *argv[])
{
    int W=75, off=0;
    if(argc>1) W  =atoi(argv[1]); iResolution[1]=W;
    if(argc>2) off=atoi(argv[2]);
    for(int y=off;1;y++) {
        std::string str="";
        for(int x=0; x<W; x++) {
            float col[4]; float fc[2]; fc[0]=y; fc[1]=x; 
            mainImage(col,fc);
            float br = col[0]*.333 + col[1]*.333 + col[2]*.333;
            float cmax = compmax3(col);
            Vec3(col2); VEC3(col2[i] = col[i]/*/cmax*/);
            str+=ansicolHT(col2,x,y);
            str+=br2c_ht((cmax+br)*.5,x,y);
            //str+=br2c_ht(br,x,y);
        }
        printf("%s\n",str.c_str());
    }
}
